#!/usr/bin/env python3
"""Check essential invariants in the PocketToons prototype SQLite database."""
import argparse
import sqlite3
import datetime as dt
import calendar
from decimal import Decimal, InvalidOperation

p=argparse.ArgumentParser()
p.add_argument('database')
args=p.parse_args()
db=sqlite3.connect(f'file:{args.database}?mode=ro', uri=True)
def valid_utc(value):
    try:
        return int(dt.datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').strftime('%Y-%m-%dT%H:%M:%SZ') == value)
    except (TypeError, ValueError):
        return 0
db.create_function('valid_utc', 1, valid_utc)
def usd_cents(value):
    """Convert an already USD-denominated two-decimal value exactly; reject excess precision."""
    try:
        amount=Decimal(str(value))
        if not amount.is_finite() or amount*100 != (amount*100).to_integral_value():
            return None
        cents=int(amount*100)
        return cents if abs(cents)<=9223372036854775807 else None
    except (InvalidOperation,TypeError,ValueError,OverflowError):
        return None
db.create_function('usd_cents', 1, usd_cents)
def next_calendar_month(value):
    try:
        current = dt.datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
        # The fixture only specifies billing days 1–25; month-end behavior is undecided.
        if current.day > 25:
            return None
        year = current.year + (current.month == 12)
        month = current.month % 12 + 1
        return current.replace(year=year, month=month, day=min(current.day, calendar.monthrange(year, month)[1])).strftime('%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError):
        return None
db.create_function('next_calendar_month', 1, next_calendar_month)
class UniqueCoverage:
    def __init__(self):
        self.ranges = []
    def step(self, start, end):
        if start is not None and end is not None and end > start:
            self.ranges.append((start,end))
    def finalize(self):
        total=0; left=right=None
        for start,end in sorted(self.ranges):
            if right is None:
                left,right=start,end
            elif start<=right:
                right=max(right,end)
            else:
                total+=right-left; left,right=start,end
        return total+(right-left if right is not None else 0)
db.create_aggregate('unique_coverage',2,UniqueCoverage)
